import { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  // Every setCount: React runs this function, builds a full
  // vnode tree (createElement calls), reconciles it against the
  // previous tree, and computes the DOM patch.
  return (
    <div className="counter">
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c + 1)}>+1</button>
    </div>
  );
}

// On each click the runtime: (1) calls Counter() again,
// (2) allocates new vnode objects, (3) diffs old vs new tree,
// (4) patches the one text node that changed.
